const inputs = $('Judge Input').all().map(i => i.json);
return $input.all().map((it, idx) => {
  let j = {}; try { j = JSON.parse(it.json.text); } catch (e) {}
  const s = Number(j.relevance_score);
  const un = Array.isArray(j.unsupported_items) ? j.unsupported_items : [];
  return { json: { id: inputs[idx].testId, judge_version: inputs[idx].version, judge_score: s || null, judge_pass: s >= 4 && un.length === 0, judge_reason: j.reason || 'no valid JSON', unsupported: un.join('; '), judgeModel: it.json.model, judgeTokens: it.json.usage?.total_tokens } };
});
